package dev.starcrownqa;
import dev.starcrown.*;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.event.TickEvent;
@Mod("starcrownqa")
public class CombatQa {
 public static final net.minecraftforge.registries.DeferredRegister<net.minecraft.world.effect.MobEffect> EFFECTS=net.minecraftforge.registries.DeferredRegister.create(net.minecraftforge.registries.ForgeRegistries.MOB_EFFECTS,"starcrownqa");
 public static final net.minecraftforge.registries.RegistryObject<net.minecraft.world.effect.MobEffect> FUTURE=EFFECTS.register("future_benefit",()->new Probe());
 private static class Probe extends net.minecraft.world.effect.MobEffect { Probe(){super(net.minecraft.world.effect.MobEffectCategory.BENEFICIAL,0xaaddff);} }
 public CombatQa(){EFFECTS.register(net.minecraftforge.fml.javafmlmod.FMLJavaModLoadingContext.get().getModEventBus());}

 static java.util.UUID liveId;static int liveTicks;
 static java.lang.reflect.Field healthField()throws Exception{for(String name:new String[]{"DATA_HEALTH_ID","f_20961_"})try{var f=net.minecraft.world.entity.LivingEntity.class.getDeclaredField(name);f.setAccessible(true);return f;}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException("Health");}
 static void require(boolean ok,String name,java.util.List<String> out){if(!ok)throw new AssertionError(name);out.add("PASS "+name);}
 static boolean ticks(net.minecraft.server.level.ServerPlayer p){try{for(var f:net.minecraft.server.level.ServerLevel.class.getDeclaredFields())if(f.getType()==net.minecraft.world.level.entity.EntityTickList.class){f.setAccessible(true);return ((net.minecraft.world.level.entity.EntityTickList)f.get(p.serverLevel())).contains(p);}}catch(ReflectiveOperationException e){throw new RuntimeException(e);}throw new IllegalStateException("tick list missing");}
 static void checkPlayer(net.minecraft.server.level.ServerPlayer p,String name,java.util.List<String> out){require(!p.isRemoved()&&p.isAlive()&&Float.isFinite(p.getHealth())&&p.getHealth()>0&&p.serverLevel().getEntity(p.getUUID())==p&&p.getServer().getPlayerList().getPlayer(p.getUUID())==p&&ticks(p),name+" health="+p.getHealth()+" registered=true",out);}
 static void avCombat(net.minecraft.server.level.ServerPlayer p){var out=new java.util.ArrayList<String>();net.minecraft.world.entity.animal.Pig pig=null;try{
  p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getAbilities().invulnerable=false;p.setInvulnerable(false);p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD,new net.minecraft.world.item.ItemStack(StarcrownDoll.ITEM.get()));DivineAnchor.unlock(p);p.setHealth(20);
  for(String name:new String[]{"com.erchien.arcanevortex.Core.CoreEntity.HealthMethodHelper","com.erchien.arcanevortex.Agent.HealthMethod.AgentHealthMethodHelper","com.erchien.arcanevortex.NativeAgent.NativeAgentHealthMethod"}){var c=Class.forName(name);c.getMethod("forceSetHealth",Object.class,float.class,float.class).invoke(null,p,0f,0f);require(!(Boolean)c.getMethod("isModified",Object.class).invoke(null,p),"forced-health table rejected: "+c.getSimpleName(),out);var f=c.getDeclaredField("HEALTH_MAP");f.setAccessible(true);require(!((java.util.Map<?,?>)f.get(null)).containsKey(p),"raw forced-health map untouched: "+c.getSimpleName(),out);checkPlayer(p,name,out);}
  var lock=Class.forName("com.erchien.arcanevortex.Help.VanShForce.HealthLockManager");lock.getMethod("lockEntityHealth",net.minecraft.world.entity.LivingEntity.class,float.class,float.class,java.util.List.class).invoke(null,p,0f,0f,java.util.List.of());require(!(Boolean)lock.getMethod("isEntityLocked",net.minecraft.world.entity.LivingEntity.class).invoke(null,p),"Arcane zero-health lock rejected",out);
  var data=healthField();@SuppressWarnings("unchecked")var key=(net.minecraft.network.syncher.EntityDataAccessor<Float>)data.get(null);p.getEntityData().set(key,0f);require(p.getEntityData().get(key)>0,"generic SynchedEntityData.set zero blocked",out);p.getEntityData().set(key,Float.NaN,true);require(Float.isFinite(p.getEntityData().get(key)),"generic forced data NaN blocked",out);
  var mod=Class.forName("com.erchien.arcanevortex.Help.HealthModifyHelp.HealthModify");for(String name:new String[]{"entityDataModify","tagModify","attributeModifier"}){require(!(Boolean)mod.getMethod(name,net.minecraft.world.entity.Entity.class,float.class).invoke(null,p,0f),"raw health API blocked: "+name,out);checkPlayer(p,name,out);}
  require(!(Boolean)mod.getMethod("forceModify",net.minecraft.world.entity.Entity.class,float.class,float.class).invoke(null,p,0f,0f),"forceModify blocked",out);
  var attacker=net.minecraftforge.common.util.FakePlayerFactory.get(p.serverLevel(),new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"AvCombatQA"));attacker.setPos(p.getX()+1,p.getY(),p.getZ());
  require(!(Boolean)mod.getMethod("traversalModify",net.minecraft.world.entity.Entity.class,net.minecraft.world.entity.Entity.class,float.class,boolean.class).invoke(null,p,attacker,0f,true),"reflection traversal blocked",out);
  var killer=Class.forName("com.erchien.arcanevortex.Help.EntityKillerHelp");for(String name:new String[]{"setEntityPos","setEntityPosReflection","removeServerLevelEntity"}){var old=p.position();require(!(Boolean)killer.getMethod(name,net.minecraft.world.entity.Entity.class).invoke(null,p),"removal/position API blocked: "+name,out);require(p.position().equals(old),"position retained after "+name,out);checkPlayer(p,name,out);}
  killer.getMethod("kill",net.minecraft.world.entity.Entity.class).invoke(null,p);killer.getMethod("killEntity",net.minecraft.world.entity.Entity.class,net.minecraft.world.entity.player.Player.class).invoke(null,p,attacker);killer.getMethod("AsynchronousRemove",net.minecraft.world.entity.Entity.class,net.minecraft.world.entity.player.Player.class).invoke(null,p,attacker);checkPlayer(p,"kill/killEntity/asynchronous removal",out);
  var td=Class.forName("com.erchien.arcanevortex.Help.TrueDamageHelper");require(!(Boolean)td.getMethod("instantKill",net.minecraft.world.entity.LivingEntity.class,net.minecraft.world.entity.Entity.class).invoke(null,p,attacker),"true-damage instant kill blocked",out);
  for(String name:new String[]{"com.erchien.arcanevortex.Core.CoreEntity.IsRemovedHelper","com.erchien.arcanevortex.Agent.AntiHiddenClass.IsRemovedHelper"}){var c=Class.forName(name);var method=java.util.Arrays.stream(c.getDeclaredMethods()).filter(m->m.getName().startsWith("set")&&m.getParameterCount()==2).findFirst().orElseThrow();method.invoke(null,p,true);require(!(Boolean)c.getMethod("containsEntity",Object.class).invoke(null,p),"fake removed-state table rejected: "+c.getSimpleName(),out);}
  var eraser=Class.forName("com.erchien.arcanevortex.Content.Item.EntityRemover.EntityRemover");var mode=Class.forName("com.erchien.arcanevortex.Content.Item.EntityRemover.EntityRemover$AttackMode");for(Object value:mode.getEnumConstants()){require(!(Boolean)eraser.getMethod("remove",net.minecraft.world.entity.Entity.class,net.minecraft.world.entity.player.Player.class,mode).invoke(null,p,attacker,value),"eraser removal mode "+value,out);var attack=eraser.getDeclaredMethod("attack",net.minecraft.world.entity.Entity.class,net.minecraft.world.entity.player.Player.class,mode);attack.setAccessible(true);require(!(Boolean)attack.invoke(null,p,attacker,value),"eraser attack mode "+value,out);checkPlayer(p,"eraser "+value,out);}
  attacker.attack(p);checkPlayer(p,"normal Player.attack entry",out);
  int tested=0;for(var item:net.minecraftforge.registries.ForgeRegistries.ITEMS){var id=net.minecraftforge.registries.ForgeRegistries.ITEMS.getKey(item);if(id==null||!id.getNamespace().equals("arcanevortex"))continue;var stack=new net.minecraft.world.item.ItemStack(item);item.onLeftClickEntity(stack,attacker,p);checkPlayer(p,"item left-click "+id,out);item.hurtEnemy(stack,p,attacker);checkPlayer(p,"item hit "+id,out);tested++;}require(tested>20,"all registered Arcane item hit callbacks tested; count="+tested,out);
  pig=net.minecraft.world.entity.EntityType.PIG.create(p.serverLevel());pig.setPos(p.getX()+8,p.getY(),p.getZ());p.serverLevel().addFreshEntity(pig);var core=Class.forName("com.erchien.arcanevortex.Core.CoreEntity.HealthMethodHelper");core.getMethod("forceSetHealth",Object.class,float.class,float.class).invoke(null,pig,0f,0f);require((Boolean)core.getMethod("isModified",Object.class).invoke(null,pig),"unprotected pig still accepts Arcane forced health",out);core.getMethod("clear",Object.class).invoke(null,pig);
  lock.getMethod("lockEntityHealth",net.minecraft.world.entity.LivingEntity.class,float.class,float.class,java.util.List.class).invoke(null,pig,0f,10f,java.util.List.of());require((Boolean)lock.getMethod("isEntityLocked",net.minecraft.world.entity.LivingEntity.class).invoke(null,pig),"unprotected pig still accepts Arcane health lock",out);lock.getMethod("unlockEntityHealth",net.minecraft.world.entity.LivingEntity.class).invoke(null,pig);
  DivineAnchor.lock(p);p.getInventory().armor.set(3,net.minecraft.world.item.ItemStack.EMPTY);killer.getMethod("removeServerLevelEntity",net.minecraft.world.entity.Entity.class).invoke(null,p);checkPlayer(p,"anchor protects with head raw-cleared",out);DivineAnchor.repair(p);out.add("IMMEDIATE_PASS");liveId=p.getUUID();liveTicks=100;
 }catch(Throwable t){out.add("FAIL "+t);t.printStackTrace();}finally{if(pig!=null)pig.discard();}try{java.nio.file.Files.write(java.nio.file.Path.of("av-combat-results.txt"),out);}catch(Exception e){e.printStackTrace();}}

 @Mod.EventBusSubscriber(modid="starcrownqa",value=net.minecraftforge.api.distmarker.Dist.CLIENT)
 public static class Client {
  static int ticks;
  @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END||++ticks%10!=0)return;var mc=net.minecraft.client.Minecraft.getInstance();mc.options.pauseOnLostFocus=false;if(mc.player==null||mc.getSingleplayerServer()==null)return;mc.mouseHandler.releaseMouse();var f=java.nio.file.Path.of("qa-command.txt");if(!java.nio.file.Files.exists(f))return;try{var lines=java.nio.file.Files.readAllLines(f);java.nio.file.Files.delete(f);for(String line:lines){if(line.equals("resume"))mc.setScreen(null);else if(line.equals("combat")){var server=mc.getSingleplayerServer();var id=mc.player.getUUID();server.execute(()->avCombat(server.getPlayerList().getPlayer(id)));}else if(line.equals("quit"))mc.stop();else if(line.equals("inspect")){java.nio.file.Files.writeString(java.nio.file.Path.of("av-client-results.txt"),"health="+mc.player.getHealth()+" max="+mc.player.getMaxHealth()+" alive="+mc.player.isAlive()+" removed="+mc.player.isRemoved()+" head="+mc.player.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.HEAD));}}}catch(Exception ex){ex.printStackTrace();}}
 }
 @Mod.EventBusSubscriber(modid="starcrownqa")
 public static class Server {
  @SubscribeEvent public static void tick(TickEvent.ServerTickEvent e){if(e.phase!=TickEvent.Phase.END||liveId==null)return;var server=net.minecraftforge.server.ServerLifecycleHooks.getCurrentServer();var p=server.getPlayerList().getPlayer(liveId);var out=new java.util.ArrayList<String>();try{checkPlayer(p,"delayed attack check",out);if(--liveTicks>0)return;out.add("PASS survived 100 real server ticks after all attack callbacks");out.add("ALL_PASS");liveId=null;java.nio.file.Files.write(java.nio.file.Path.of("av-combat-live-results.txt"),out);}catch(Throwable t){out.add("FAIL "+t);liveId=null;try{java.nio.file.Files.write(java.nio.file.Path.of("av-combat-live-results.txt"),out);}catch(Exception ignored){}t.printStackTrace();}}
 }
}
